const crypto = require('crypto');

// Secret key del webhook configurado en Taiga (Project Settings → Integrations → Webhooks → "key").
// Si cada proyecto usa una key distinta, cambiar esto por un mapa { 'Nombre Proyecto': 'key' }.
const TAIGA_WEBHOOK_SECRET = '__TAIGA_WEBHOOK_SECRET__';

const item = $input.first();
const signature = item.json.headers?.['x-taiga-webhook-signature'];

if (!signature) {
  throw new Error('Rechazado: falta el header x-taiga-webhook-signature.');
}

const rawBase64 = item.binary?.data?.data;
if (!rawBase64) {
  throw new Error('Rechazado: no llegó el raw body. Activar la opción "Raw Body" en el nodo Webhook.');
}

const rawBody = Buffer.from(rawBase64, 'base64');
const expectedSignature = crypto
  .createHmac('sha1', TAIGA_WEBHOOK_SECRET)
  .update(rawBody)
  .digest('hex');

if (expectedSignature !== signature) {
  throw new Error('Rechazado: firma de webhook inválida (x-taiga-webhook-signature no coincide).');
}

return [item];

const raw = $input.first().json.body;
const { action, type, by, data, change } = raw;

const COLORS = {
  create: 5763719,
  delete: 15548997,
  change: 5793266,
  comment: 16705372
};

const TYPE_LABELS = {
  userstory: 'Historia de usuario',
  issue: 'Incidencia',
  task: 'Tarea',
  epic: 'Épica',
  milestone: 'Hito',
  wikipage: 'Página Wiki'
};

const TAIGA_BASE = 'https://taiga.ewcam.co';

const DISCORD_WEBHOOKS = {
  'Nuevo SIGW':     '__WEBHOOK-URL__',
  'Soporte':        '__WEBHOOK-URL__',
  'Desarrollo':     '__WEBHOOK-URL__',
  'Redna Models':   '__WEBHOOK-URL__',
  'GESTIÓN HUMANA': '__WEBHOOK-URL__',
  'Contabilidad':   '__WEBHOOK-URL__',
  'Tienda Webcam':  '__WEBHOOK-URL__',
  'Tesoreria':      '__WEBHOOK-URL__',
  'Fotografia':     '__WEBHOOK-URL__',
  'Asesores':       '__WEBHOOK-URL__',
  'Marketing':      '__WEBHOOK-URL__',
  '_default':       '__WEBHOOK-URL__'
};

// Canales por DEPARTAMENTO (atributo personalizado "DEPARTAMENTO" en épicas/US/tareas/issues).
// Cuando el objeto trae ese atributo, prima sobre el canal por proyecto.
// Taiga lo manda plano: data.custom_attributes_values.DEPARTAMENTO
const DEPARTMENT_WEBHOOKS = {
  'CONTABILIDAD': DISCORD_WEBHOOKS['Contabilidad'],
  'SOPORTE':      DISCORD_WEBHOOKS['Soporte'],
  'ASESORES':     DISCORD_WEBHOOKS['Asesores'],
  'RRHH':         DISCORD_WEBHOOKS['GESTIÓN HUMANA'],
  'FOTOGRAFIA':   DISCORD_WEBHOOKS['Fotografia'],
  'MARKETING':    DISCORD_WEBHOOKS['Marketing'],
  'DESARROLLO':   DISCORD_WEBHOOKS['Desarrollo'],
  'GERENCIA':     '__WEBHOOK-URL__', // TODO: sin canal propio en Discord todavía
  'COMERCIAL':    '__WEBHOOK-URL__'  // TODO: sin canal propio en Discord todavía
};

const departmentValue = data?.custom_attributes_values?.DEPARTAMENTO;
const departmentUrl = departmentValue && DEPARTMENT_WEBHOOKS[departmentValue];

const discordUrl =
  (departmentUrl && departmentUrl !== '__WEBHOOK-URL__' ? departmentUrl : null) ||
  DISCORD_WEBHOOKS[data?.project?.name] ||
  DISCORD_WEBHOOKS['_default'];

const typeLabel = TYPE_LABELS[type] || type;
const actor = by?.full_name || by?.username || 'Desconocido';
const subject = data?.subject || data?.name || 'Sin título';
const isComment = action === 'change' && change?.comment;

// Formatea un valor de diff: strings/numbers tal cual, objetos por su full_name/name/subject.
function formatDiffValue(v) {
  if (v === null || v === undefined || v === '') return '—';
  if (typeof v === 'object') return v.full_name || v.name || v.subject || JSON.stringify(v);
  return String(v);
}

let color, title, description = '';

if (action === 'create') {
  color = COLORS.create;
  title = `✅ ${typeLabel} creado: ${subject}`;
  description = data?.description ? data.description.substring(0, 300) : '';
} else if (action === 'delete') {
  color = COLORS.delete;
  title = `🗑️ ${typeLabel} eliminado: ${subject}`;
} else if (isComment) {
  color = COLORS.comment;
  title = `💬 Comentario en ${typeLabel}: ${subject}`;
  description = change.comment.substring(0, 1000);
} else if (action === 'change') {
  color = COLORS.change;
  title = `✏️ ${typeLabel} actualizado: ${subject}`;
  const diffs = change?.diff || {};
  const lines = [];

  // Los custom attributes (ej. DEPARTAMENTO) vienen en una forma distinta al resto del diff.
  if (diffs.custom_attributes) {
    for (const c of diffs.custom_attributes.changed || []) {
      const [from, to] = c.changes?.value || [];
      lines.push(`**${c.name}**: ~~${formatDiffValue(from)}~~ → ${formatDiffValue(to)}`);
    }
    for (const c of diffs.custom_attributes.new || []) {
      lines.push(`**${c.name}** definido`);
    }
  }

  for (const [k, v] of Object.entries(diffs)) {
    if (k === 'custom_attributes') continue;
    if (v && typeof v === 'object' && ('from' in v || 'to' in v)) {
      lines.push(`**${k}**: ~~${formatDiffValue(v.from)}~~ → ${formatDiffValue(v.to)}`);
    } else {
      lines.push(`**${k}** modificado`);
    }
  }

  description = lines.join('\n') || 'Actualizado';
}

const fields = [];
if (data?.ref) fields.push({ name: 'Referencia', value: `#${data.ref}`, inline: true });
if (data?.status?.name) fields.push({ name: 'Estado', value: data.status.name, inline: true });
if (data?.assigned_to?.full_name) fields.push({ name: 'Asignado a', value: data.assigned_to.full_name, inline: true });
if (data?.project?.name) fields.push({ name: 'Proyecto', value: data.project.name, inline: true });
if (departmentValue) fields.push({ name: 'Departamento', value: departmentValue, inline: true });

const url = data?.permalink || data?.project?.permalink || TAIGA_BASE;

fields.push({ name: 'Enlace', value: `[Ver en Taiga](${url})`, inline: false });

const embed = {
  title: title?.substring(0, 256),
  color,
  fields,
  author: {
    name: actor,
    icon_url: by?.photo || undefined,
    url: by?.permalink || undefined
  },
  timestamp: new Date().toISOString()
};

if (data?.project?.logo_big_url) embed.thumbnail = { url: data.project.logo_big_url };
if (description) embed.description = description.substring(0, 4096);
if (url) embed.url = url;

return [{ json: { discordUrl, embeds: [embed] } }];
